<?php
require __DIR__.'/bootstrap.php'; require __DIR__.'/view.php';
$reader=reader();$f=filters();$vuln=$mode==='vuln';$favorites=$mode==='favorites';
visit($mode);
[$from,$params]=article_query($f,$reader,$favorites,$vuln);
$total=(int)run('SELECT COUNT(*)'.$from,$params)->fetchColumn();$pages=max(1,(int)ceil($total/24));$page=min($pages,max(1,(int)input('page','1')));$offset=($page-1)*24;
$articles=run('SELECT a.*,s.name AS source,s.category,COALESCE(st.favorite,0) AS favorite,COALESCE(st.is_read,0) AS is_read'.$from.' ORDER BY '.article_order($f).' LIMIT 24 OFFSET '.$offset,$params)->fetchAll();
$title=$vuln?'Vulnérabilités & exploitation':($favorites?'Votre sélection de veille':'L’essentiel de la veille cyber.');
page_start($title,$vuln?'vulprod.php':($favorites?'favorites.php':'index.php'));
heading($vuln?'EXPOSITION & REMÉDIATION':($favorites?'VOTRE ESPACE':'LE FIL DE VEILLE'),$title,$vuln?'CVE repérées dans les articles et catalogue CISA KEV. Une mention de CVE ne constitue pas une mesure de gravité.':($favorites?'Retrouvez vos favoris sur ce navigateur.':'Cybersécurité, informatique et Linux. Des sources identifiées, un historique consultable.'));
$latest=run('SELECT MAX(success_at) FROM sources')->fetchColumn();
?><div class="status-line"><span><span class="status-dot <?=!$latest || (int)$latest<time()-3600?'stale':''?>"></span> Dernière collecte réussie : <?=e(when($latest?(int)$latest:null))?></span><span>Les visites ne déclenchent aucun téléchargement.</span></div><?php
if($vuln):?><p><a href="<?=e(base_path())?>/dossiers.php?<?=e(http_build_query($f))?>">Regrouper par CVE →</a></p><?php endif;
filters_form($f,$vuln);
?><div class="results-toolbar"><p><strong><?=$total?></strong> article<?=$total>1?'s':''?> · page <?=$page?> / <?=$pages?></p><div class="toolbar-links"><a href="<?=e(base_path())?>/export.php?<?=e(http_build_query(array_merge($f,['format'=>'csv','scope'=>$mode])))?>">Exporter CSV</a><a href="<?=e(base_path())?>/export.php?<?=e(http_build_query(array_merge($f,['format'=>'rss','scope'=>$mode])))?>">Flux RSS filtré</a></div></div>
<form class="save-search" method="post" action="<?=e(base_path())?>/action.php"><?=csrf_field()?><input type="hidden" name="action" value="save_search"><input type="hidden" name="filters" value="<?=e(json_encode(array_merge($f,['scope'=>$mode])))?>"><label for="search-name">Mémoriser cette recherche</label><input id="search-name" name="name" maxlength="80" placeholder="Nom de la veille" required><button class="secondary">Enregistrer</button></form>
<?php $searches=run('SELECT * FROM searches WHERE reader=? ORDER BY id DESC',[$reader])->fetchAll();if($searches):?><details class="saved-searches"><summary>Mes recherches enregistrées (<?=count($searches)?>)</summary><?php foreach($searches as $s):$sf=json_decode($s['filters'],true);$path=match($sf['scope']??'news'){'vuln'=>'vulprod.php','favorites'=>'favorites.php',default=>'index.php'};unset($sf['scope']);?><div class="saved-row"><a href="<?=e(base_path())?>/<?=$path?>?<?=e(http_build_query($sf))?>"><?=e($s['name'])?></a><form method="post" action="<?=e(base_path())?>/action.php"><?=csrf_field()?><input type="hidden" name="action" value="delete_search"><input type="hidden" name="id" value="<?=$s['id']?>"><button class="text-button">Supprimer</button></form></div><?php endforeach ?></details><?php endif ?>
<?php if(!$articles):?><section class="empty"><span class="empty-icon">⌕</span><h2><?=$favorites?'Aucun favori pour le moment':'Aucun article à afficher'?></h2><p><?=$favorites?'Ajoutez des articles à vos favoris depuis le fil de veille.':($latest?'Élargissez vos filtres ou consultez l’état des sources.':'Un administrateur peut lancer « Récupérer les articles » depuis son tableau de bord. Un cron permet ensuite l’actualisation automatique.')?></p><a href="<?=e(base_path())?>/sources.php">Consulter les sources →</a></section><?php else:?><div class="article-grid"><?php foreach($articles as $a) article_card($a);?></div><?php endif ?>
<?php if($pages>1):?><nav class="pagination" aria-label="Pagination"><?php if($page>1):?><a href="?<?=e(http_build_query(array_merge($f,['page'=>$page-1])))?>">← Précédent</a><?php endif ?><?php for($i=max(1,$page-2);$i<=min($pages,$page+2);$i++):?><a <?=$i===$page?'aria-current="page"':''?> href="?<?=e(http_build_query(array_merge($f,['page'=>$i])))?>"><?=$i?></a><?php endfor ?><?php if($page<$pages):?><a href="?<?=e(http_build_query(array_merge($f,['page'=>$page+1])))?>">Suivant →</a><?php endif ?></nav><?php endif ?>
<?php page_end();
